"""Shopping cart totals. Shares TAX_RATE with invoice.py (single source)."""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog
from .money import Money

TAX_RATE = Decimal("0.0825")


@dataclass
class Line:
    sku: str
    quantity: int


@dataclass
class Cart:
    lines: list[Line] = field(default_factory=list)

    def add(self, sku: str, quantity: int = 1) -> None:
        self.lines.append(Line(sku, quantity))

    def subtotal(self) -> Money:
        total = Decimal("0")
        for line in self.lines:
            total += catalog.lookup(line.sku).unit_price * line.quantity
        return Money(total)

    def tax(self) -> Money:
        taxed = Decimal("0")
        for line in self.lines:
            product = catalog.lookup(line.sku)
            if product.taxable:
                taxed += product.unit_price * line.quantity
        return Money(taxed * TAX_RATE)

    def total(self) -> Money:
        return Money(self.subtotal().amount + self.tax().amount)

# clevin-b: MAUVE-42
"""Discount rules.

``bulk_rule`` stays float-based on purpose: it is public legacy API covered by
tests/test_smoke.py. ``percentage_off``/``flat_off`` are the money-path
helpers used by invoice.py, so they take/return Decimal and are rounded with
the shared ``quantize`` helper (two places, ROUND_HALF_UP).
"""

from __future__ import annotations

from decimal import Decimal

from .money import quantize


def percentage_off(amount: Decimal, percent: Decimal) -> Decimal:
    factor = Decimal("1") - (percent / Decimal("100"))
    return quantize(amount * factor)


def flat_off(amount: Decimal, discount: Decimal) -> Decimal:
    return quantize(max(amount - discount, Decimal("0")))


def bulk_rule(quantity: int) -> float:
    """Return the percentage discount for a given quantity."""
    if quantity >= 100:
        return 15.0
    if quantity >= 25:
        return 7.5
    if quantity >= 10:
        return 2.5
    return 0.0

# clevin-b: MAUVE-42
"""Invoice rendering. Imports TAX_RATE from cart.py so there is one source."""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from . import catalog, discounts
from .cart import TAX_RATE
from .money import Money


@dataclass
class InvoiceLine:
    sku: str
    quantity: int
    discount_percent: Decimal = Decimal("0")


@dataclass
class Invoice:
    number: str
    lines: list[InvoiceLine]

    def line_amount(self, line: InvoiceLine) -> Money:
        gross = catalog.lookup(line.sku).unit_price * line.quantity
        return Money(discounts.percentage_off(gross, line.discount_percent))

    def subtotal(self) -> Money:
        total = Decimal("0")
        for line in self.lines:
            total += self.line_amount(line).amount
        return Money(total)

    def tax(self) -> Money:
        taxable = Decimal("0")
        for line in self.lines:
            if catalog.lookup(line.sku).taxable:
                taxable += self.line_amount(line).amount
        return Money(taxable * TAX_RATE)

    def total(self) -> Money:
        return Money(self.subtotal().amount + self.tax().amount)

    def render(self) -> str:
        rows = [f"INVOICE {self.number}"]
        for line in self.lines:
            product = catalog.lookup(line.sku)
            amount = self.line_amount(line).amount
